// Builds the bookmarklet link for the package typed in the box.
const a = document.getElementById('bm') as HTMLAnchorElement
const input = document.getElementById('pkg') as HTMLInputElement
function update() {
  const pkg = input.value.trim()
  const origin = location.origin
  const js = `(function(){if(window.__yrS4)return;var s=document.createElement('script');s.src='${origin}/overlay/v1/yrS4.js?t='+Date.now();s.dataset.package=${JSON.stringify(pkg)};s.dataset.platform='${origin}';document.body.appendChild(s)})();`
  a.href = 'javascript:' + encodeURIComponent(js)
}
input.addEventListener('input', update)
update()
a.addEventListener('click', (e) => {
  if (location.pathname.startsWith('/')) {
    e.preventDefault()
    alert('Drag this link to your bookmarks bar, then click it while viewing a page of the book.')
  }
})
